  'priv.zero.title': "ઝીરો ડેટા કલેક્શન પોલિસી",
  'priv.zero.body': "OpenAlgo અને OpenAlgo Web Portal કોઈ પણ પ્રકારનો યુઝર ડેટા કલેક્ટ, સ્ટોર, ટ્રાન્સમિટ કે પ્રોસેસ કરતા નથી. ત્યાં કોઈ એનાલિટિક્સ નથી, કોઈ ટેલિમેટ્રી નથી, કોઈ ટ્રેકિંગ કૂકીઝ નથી, કોઈ યુઝર બિહેવિયર મોનિટરિંગ નથી, અને કોઈ પણ પ્રકારનું ડેટા કલેક્શન નથી.",
  'priv.dont.title': "અમે શું કલેક્ટ કરતા નથી",
