  'priv.dont.i2l': "કોઈ યુસેજ ડેટા નહીં:",
  'priv.dont.i2d': "તમે પ્લેટફોર્મ કેવી રીતે વાપરો છો કે કયા ફીચર્સ એક્સેસ કરો છો તે અમે ટ્રેક કરતા નથી",
  'priv.dont.i3l': "કોઈ ટ્રેડિંગ ડેટા નહીં:",
  'priv.dont.i3d': "તમારી સ્ટ્રેટેજી, ટ્રેડ્સ અને ફાઇનાન્શિયલ માહિતી સંપૂર્ણપણે પ્રાઇવેટ રહે છે",
