  'priv.dont.i4d': "કોઈ Google Analytics નહીં, કોઈ ટ્રેકિંગ પિક્સેલ્સ નહીં, કોઈ થર્ડ-પાર્ટી મોનિટરિંગ નહીં",
  'priv.dont.i5l': "કોઈ કૂકીઝ નહીં:",
  'priv.dont.i5d': "અમે ટ્રેકિંગ કૂકીઝ કે ટ્રેકિંગ માટે કોઈ પણ પ્રકારના બ્રાઉઝર સ્ટોરેજનો ઉપયોગ કરતા નથી",
  'priv.dont.i6l': "કોઈ સર્વર લોગ્સ નહીં:",
  'priv.dont.i6d': "અમે તમારી પ્રવૃત્તિઓ કે એક્સેસ પેટર્નના લોગ્સ જાળવતા નથી",
  'priv.self.title': "સેલ્ફ-હોસ્ટેડ આર્કિટેક્ચર",
  'priv.self.intro': "OpenAlgo ને તમારા પોતાના ઇન્ફ્રાસ્ટ્રક્ચર પર સેલ્ફ-હોસ્ટ કરવા માટે ડિઝાઇન કરવામાં આવ્યું છે. તેનો અર્થ છે:",
  'priv.self.i1': "તમામ ડેટા તમારા સંપૂર્ણ કંટ્રોલ હેઠળ તમારા સર્વર્સ પર જ રહે છે",
