  'priv.trans.title': "પારદર્શિતા",
  'priv.trans.intro': "OpenAlgo AGPL-3.0 લાઇસન્સ હેઠળ સંપૂર્ણપણે ઓપન-સોર્સ છે. તમે આ કરી શકો છો:",
