  'priv.trans.i2': "ચકાસી શકો છો કે કોઈ ડેટા કલેક્શન કોડ અસ્તિત્વમાં નથી",
  'priv.trans.i3': "સંપૂર્ણ ખાતરી માટે સોર્સમાંથી બિલ્ડ અને ડિપ્લોય કરી શકો છો",
  'priv.trans.i4': "પ્રોજેક્ટમાં કન્ટ્રિબ્યુટ કરી શકો છો અને પ્રાઇવસી સ્ટાન્ડર્ડ્સ જાળવવામાં મદદ કરી શકો છો",
