  'priv.third.i2': "ડોક્યુમેન્ટેશન અને સોર્સ કોડ હોસ્ટ કરવા માટે GitHub",
  'priv.third.note': "નોંધ: OpenAlgo એપ્લિકેશન પોતે, જ્યારે સેલ્ફ-હોસ્ટેડ હોય, ત્યારે કોઈ પણ થર્ડ-પાર્ટી સર્વિસનો ઉપયોગ કરતી નથી.",
  'priv.changes.title': "આ પોલિસીમાં ફેરફારો",
  'priv.changes.body': "ઝીરો ડેટા કલેક્શન પ્રત્યેની અમારી પ્રતિબદ્ધતા કાયમી છે. આ પોલિસીમાં કોઈ પણ અપડેટ ફક્ત અમારા પ્રાઇવસી સ્ટેન્સને સ્પષ્ટ કરશે અથવા મજબૂત બનાવશે, ક્યારેય નબળું નહીં કરે.",
