  'skill.heroDesc': 'OpenAlgo Skills તમારા AI આસિસ્ટન્ટમાં રેડીમેડ ટ્રેડિંગ નોલેજ ઉમેરે છે - ચાર્ટ્સ, સ્કેનર્સ, કસ્ટમ ઇન્ડિકેટર્સ, અને રિયલિસ્ટિક બ્રોકરેજ ખર્ચ સાથે સંપૂર્ણ બેકટેસ્ટ્સ.',
  'skill.heroDesc2': 'કોઈ કોડિંગ અનુભવ જરૂરી નથી. ફક્ત તમારા AI ને સાદી ભાષામાં કહો કે તમારે શું જોઈએ છે અને તે કામ કરી દેશે.',
