  'skill.whatSub': 'Skill ને તમારા AI માટે પ્લગ-ઇન જેવું સમજો. તેને એકવાર ઇન્સ્ટોલ કરો અને તમારું AI નવી ક્ષમતાઓ મેળવે છે - જેમ કે ઇન્ડિકેટર ચાર્ટ કરવો, સ્ટોક્સ સ્કેન કરવા, અથવા સંપૂર્ણ બેકટેસ્ટ ચલાવવો, બધું એક જ ઇન્સ્ટ્રક્શનમાં.',
