  'skill.w1d': 'કોઈ લાંબા પ્રોમ્પ્ટ્સ નહીં, ટ્યુટોરિયલ્સમાંથી કોડ કૉપી-પેસ્ટ કરવાની જરૂર નહીં. ફક્ત પૂછો, અને તમારા AI ને પહેલેથી જ ખબર છે કેવી રીતે.',
