  'skill.btTitle': 'બેકટેસ્ટિંગ Skills',
  'skill.btDesc': 'તમારા ટ્રેડિંગ આઇડિયા વાસ્તવિક ભૂતકાળના ડેટા પર ટેસ્ટ કરો. ભારતીય, US, અને ક્રિપ્ટો માર્કેટ્સ માટે ફી, ટેક્સ, અને સ્લિપેજ પહેલેથી જ ઉમેરેલા છે - જેથી પરિણામો તમને ખરેખર તમારા એકાઉન્ટમાં દેખાય તે દર્શાવે.',
