  // Batch D
  // MCP page
  'mcp.copy': "ક્લિપબોર્ડ પર કૉપિ કરો",
  'mcp.hero.badge1': "ઓપન સોર્સ",
  'mcp.hero.badge2': "Claude અને ChatGPT સાથે કામ કરે છે",
  'mcp.hero.badge3': "તમારા કમ્પ્યુટર પર ચાલે છે",
  'mcp.hero.h1a': "ટ્રેડ કરો ફક્ત",
  'mcp.hero.h1b': "તમારા AI ને પૂછીને",
  'mcp.hero.desc': "OpenAlgo MCP તમારી AI ચેટ એપ - Claude, Cursor, Windsurf, અથવા ChatGPT - ને તમારા OpenAlgo ટ્રેડિંગ એકાઉન્ટ સાથે જોડે છે. ફક્ત તેની સાથે વાત કરીને ઓર્ડર મૂકો, પોઝિશન્સ ચેક કરો, અને લેટેસ્ટ ભાવ મેળવો.",
  'mcp.hero.sub': "કોઈ ડેશબોર્ડ નહીં. કોઈ ક્લિકિંગ નહીં. ફક્ત તમારે જે જોઈએ છે તે ટાઈપ કરો, અને તમારું AI તમારા બ્રોકર મારફતે તે પૂરું કરી દેશે.",
  'mcp.hero.ctaQuickstart': "ક્વિકસ્ટાર્ટ",
  'mcp.hero.ctaGithub': "GitHub પર જુઓ",
  'mcp.hero.ctaDocs': "ડોક્સ",
  'mcp.chat.title': "આ કેવું અનુભવાય છે",
  'mcp.chat.sub': "અહીં એક ટ્રેડર અને તેમના AI વચ્ચેની વાસ્તવિક વાતચીત છે. નોંધ કરો કે તમે ક્યારેય ડેશબોર્ડને સ્પર્શ પણ ન કર્યો.",
  'mcp.chat.user': "મને બેન્કિંગમાં નબળાઈ દેખાઈ રહી છે. BANKNIFTY ઓપ્શન્સમાં મારી MIS પોઝિશન્સ સ્ક્વેર ઓફ કરો અને મને P&L બતાવો.",
  'mcp.chat.ai1': "થઈ રહ્યું છે. પહેલા હું તમારી BANKNIFTY MIS પોઝિશન્સ ખેંચી લાવું છું...",
  'mcp.chat.ai2': "હવે બંને બંધ કરી રહ્યો છું...",
  'mcp.chat.done': "થઈ ગયું. આજનું રિયલાઇઝ્ડ P&L:",
  'mcp.chat.note': "ઉદાહરણ વાતચીત. તમારું AI શોધખોળ કરે છે અને એક્ઝિક્યુટ કરે છે - તમારે ફક્ત કન્ફર્મ કરવાનું અને જોવાનું છે.",
  'mcp.why.title': "ટ્રેડર્સ તેને શા માટે પસંદ કરે છે",
  'mcp.why.sub': "એવા ટ્રેડર્સ માટે બનાવ્યું છે જેઓ સાત સ્ક્રીન્સ પર ક્લિક કરવાને બદલે ફક્ત તેમને શું જોઈએ છે તે કહેવાનું પસંદ કરે છે.",
  'mcp.cap1t': "ક્લિક નહીં, વાત કરો",
  'mcp.cap1d': "\"RELIANCE ના 100 શેર માર્કેટ ભાવે ખરીદો.\" બસ આટલું જ. કોઈ ફોર્મ નહીં, કોઈ મેનુ નહીં - ફક્ત તમારા AI ને શું કરવું તે કહો.",
  'mcp.cap2t': "એક સૂચના, અનેક પગલાં",
  'mcp.cap2d': "\"મારી પોઝિશન્સ ચેક કરો અને નુકસાનવાળી બંધ કરો\" કહો અને તમારું AI બંને એક જ વારમાં કરી દેશે.",
  'mcp.cap3t': "માંગ પર લાઇવ ભાવ",
  'mcp.cap3d': "તમારી ચેટની અંદર જ ક્વોટ્સ, માર્કેટ ડેપ્થ, અથવા હિસ્ટોરિકલ ચાર્ટ્સ માટે પૂછો. વાસ્તવિક આંકડા, રિયલ ટાઇમમાં.",
  'mcp.cap4t': "તમારો ડેટા તમારી પાસે જ રહે છે",
  'mcp.cap4d': "બધું તમારા પોતાના કમ્પ્યુટર પર ચાલે છે. તમારી API કી અને ટ્રેડ્સ ક્યારેય તમારા મશીનની બહાર જતા નથી.",
  'mcp.cap5t': "એ જ ચેટ, કોઈપણ બ્રોકર",
  'mcp.cap5d': "OpenAlgo સપોર્ટ કરે છે તેવા દરેક બ્રોકર સાથે કામ કરે છે. કંઈ નવું શીખ્યા વગર બ્રોકર બદલો.",
  'mcp.cap6t': "40+ બિલ્ટ-ઇન એક્શન્સ",
  'mcp.cap6d': "ઓર્ડર મૂકો, ઓપ્શન્સ ટ્રેડ કરો, ફંડ્સ ચેક કરો, Greeks મેળવો, સિમ્બોલ્સ શોધો - તમારા AI ને પહેલેથી જ ખબર છે કેવી રીતે કરવું.",
  'mcp.how.title': "આ કેવી રીતે કામ કરે છે",
  'mcp.how.sub': "તમે વાત કરો, તમારું AI પગલું ભરે છે, OpenAlgo તેને ચલાવે છે, તમારો બ્રોકર એક્ઝિક્યુટ કરે છે. ચાર પગલાં - અને તમારે ફક્ત પહેલું જ સંભાળવાનું છે.",
  'mcp.how.step': "પગલું {n}",
  'mcp.flow1t': "તમે પૂછો",
  'mcp.flow1d': "\"મારી ઓપન પોઝિશન્સ બતાવો અને નુકસાનવાળી બંધ કરો.\"",
  'mcp.flow2t': "AI સમજે છે",
  'mcp.flow2d': "Claude, Cursor, Windsurf, અથવા ChatGPT સમજી લે છે કે તમારે શું જોઈએ છે.",
  'mcp.flow3t': "OpenAlgo પગલું ભરે છે",
  'mcp.flow3d': "તમારા કમ્પ્યુટર પર ચાલી રહેલું તમારું OpenAlgo રિક્વેસ્ટ સંભાળે છે.",
  'mcp.flow4t': "બ્રોકર એક્ઝિક્યુટ કરે છે",
  'mcp.flow4d': "ઓર્ડર તમારા બ્રોકર પાસે જાય છે અને એક્સચેન્જ સુધી પહોંચે છે - હંમેશની જેમ જ.",
  'mcp.prompts.title': "તમે ફક્ત આટલું પૂછી શકો છો",
  'mcp.prompts.sub': "એકવાર તમે સેટઅપ કરી લો પછી આમાંથી કોઈપણ તરત જ કામ કરે છે. કોઈ ખાસ શબ્દરચનાની જરૂર નથી - કુદરતી રીતે બોલો.",
  'mcp.prompt1': "RELIANCE ના 100 શેર માટે માર્કેટ ભાવે બાય ઓર્ડર મૂકો",
  'mcp.prompt2': "મને મારી હાલની પોઝિશન્સ અને આજનું P&L બતાવો",
