  'mcp.prompt5': "મારી પાસે કેટલું માર્જિન ઉપલબ્ધ છે?",
  'mcp.prompt6': "છેલ્લા ટ્રેડિંગ દિવસ માટે BANKNIFTY નો 5-મિનિટનો હિસ્ટોરિકલ ડેટા મેળવો",
  'mcp.prompt7': "આ ગુરુવારે એક્સપાયર થતા બધા સાપ્તાહિક NIFTY ઓપ્શન્સ શોધો",
  'mcp.prompt8': "બપોરે 3:15 પહેલા મારી બધી MIS પોઝિશન્સ બંધ કરો",
  'mcp.tools.title': "તમે જે બધું કરી શકો છો",
  'mcp.tools.sub': "OpenAlgo જે કંઈ કરી શકે છે, તે હવે તમારું AI તમારા માટે કરી શકે છે. ટ્રેડર્સ ખરેખર જે રીતે વિચારે છે તે રીતે ગ્રુપ કરેલું છે.",
