  'mcp.tg1.i2l': "સ્માર્ટ ઓર્ડર",
  'mcp.tg1.i2d': "તમારી હાલની પોઝિશન સાઈઝ પ્રમાણે આપોઆપ એડજસ્ટ થાય છે",
  'mcp.tg1.i3l': "બાસ્કેટ ઓર્ડર્સ",
  'mcp.tg1.i3d': "એક જ વારમાં અનેક ઓર્ડર્સ મોકલો (જેમ કે ઓપ્શન સ્પ્રેડ્સ)",
