  'sip.srv.sharedTitle': "શેર્ડ CPU",
  'sip.srv.sharedDesc': "શેર્ડ એપાર્ટમેન્ટ જેવું. રિસોર્સિસ અનેક યુઝર્સ વચ્ચે વહેંચાયેલા હોય છે. સસ્તું પણ પરફોર્મન્સ બદલાય છે.",
