  'sip.srv.dedDesc': "તમારી પોતાની પ્રાઇવેટ વિલા જેવું. રિસોર્સિસ ફક્ત તમારા જ છે. ઝડપી અને વધુ સુસંગત પરફોર્મન્સ.",
